"""Text normalization helpers."""
import re


def slugify(s):
    """Turn a human title into a URL slug (lowercase, words joined by hyphens)."""
    lowered = s.lower()
    words = re.findall(r'[a-z0-9]+', lowered)
    return '-'.join(words)


def titlecase(s):
    return " ".join(w.capitalize() for w in s.split())
